package vn.sland.controller;

import jakarta.servlet.http.HttpSession;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import vn.sland.repository.AppRepository;import vn.sland.service.GeminiService;import vn.sland.util.WebUtil;import java.util.*;

@Controller
public class ChatController extends BaseController {
 private final AppRepository repo;private final GeminiService gemini;public ChatController(AppRepository repo,GeminiService gemini){this.repo=repo;this.gemini=gemini;}
 @GetMapping("/admin_chat.php")String admin(@RequestParam(name="user_id",required=false)Integer uid,Model m,HttpSession s){if(!WebUtil.admin(s))return "redirect:/login.php";base(m,s,"Chat khách hàng");m.addAttribute("users",repo.list("SELECT u.id,u.username,(SELECT message FROM messages WHERE (sender_id=u.id AND receiver_id=0) OR (sender_id=0 AND receiver_id=u.id) ORDER BY created_at DESC LIMIT 1) last_msg,(SELECT created_at FROM messages WHERE (sender_id=u.id AND receiver_id=0) OR (sender_id=0 AND receiver_id=u.id) ORDER BY created_at DESC LIMIT 1) last_time FROM users u WHERE u.id IN (SELECT DISTINCT sender_id FROM messages WHERE receiver_id=0) OR u.id IN (SELECT DISTINCT receiver_id FROM messages WHERE sender_id=0) ORDER BY last_time DESC"));m.addAttribute("currentUid",uid);m.addAttribute("messages",uid==null?List.of():repo.list("SELECT * FROM messages WHERE (sender_id=? AND receiver_id=0) OR (sender_id=0 AND receiver_id=?) ORDER BY created_at",uid,uid));return "admin_chat";}
 @PostMapping("/chat_backend.php")@ResponseBody Map<String,Object> chat(@RequestParam(required=false)String action,@RequestParam(required=false)String message,@RequestParam(name="user_id",required=false)Integer userId,HttpSession s){if("load".equals(action)||"history".equals(action)){if(!WebUtil.logged(s))return Map.of("status","error");int uid=WebUtil.admin(s)&&userId!=null?userId:WebUtil.intv(s.getAttribute("user_id"));var rows=repo.list("SELECT * FROM messages WHERE (sender_id=? AND receiver_id=0) OR (sender_id=0 AND receiver_id=?) ORDER BY created_at",uid,uid);return Map.of("status","success","messages",rows,"history",rows);}if(message==null||message.trim().isBlank())return Map.of("status","error","message","Tin nhắn trống");if(!WebUtil.logged(s))return Map.of("status","error","message","Vui lòng đăng nhập");if(WebUtil.admin(s)){if(userId==null)return Map.of("status","error");repo.update("INSERT INTO messages(sender_id,receiver_id,message,created_at) VALUES(0,?,?,NOW())",userId,message.trim());return Map.of("status","success");}int uid=WebUtil.intv(s.getAttribute("user_id"));repo.update("INSERT INTO messages(sender_id,receiver_id,message,created_at) VALUES(?,0,?,NOW())",uid,message.trim());String ai=gemini.reply("Bạn là tư vấn viên nội thất SLAND. Hãy trả lời ngắn gọn, lịch sự bằng tiếng Việt. Khách hỏi: "+message);return Map.of("status","success","ai_reply",ai,"reply",ai);}
}
